        tokens = list(lexer.tokenize(expression))
        return [
            {
                "type": token["type"],
                "value": token["value"],
                "start": token["start"],
                "end": token["end"]
            }
            for token in tokens
        ]
    except Exception as e:
        raise ValueError(f"Failed to tokenize JMESPath expression: {str(e)}")
